function pointInRing(longitude: number, latitude: number, ring: Position[]): boolean {
  let inside = false;

  for (let index = 0, previous = ring.length - 1; index < ring.length; previous = index++) {
    const [currentLongitude, currentLatitude] = ring[index];
    const [previousLongitude, previousLatitude] = ring[previous];

    const intersects =
      currentLatitude > latitude !== previousLatitude > latitude &&
      longitude <
        ((previousLongitude - currentLongitude) * (latitude - currentLatitude)) /
          (previousLatitude - currentLatitude) +
          currentLongitude;

    if (intersects) {
      inside = !inside;
    }
  }

  return inside;
}

/**
 * Returns true only for a point on India's land boundary. Points in a polygon
 * hole are excluded. This intentionally excludes Sri Lanka and neighbouring
 * countries that are also inside the broad FIRMS rectangular query.
 */
export function isPointInIndia(latitude: number, longitude: number): boolean {
  return INDIA_BOUNDARY.some((polygon) => {
    const [outerRing, ...holes] = polygon;
    return (
      pointInRing(longitude, latitude, outerRing) &&
      !holes.some((hole) => pointInRing(longitude, latitude, hole))
    );
  });
}
